window.ICT_TEACHING_DATA={"scenarios":[{"id":"journey","unit":"ICT-001.02","title":"同一份数据，逐段交给谁？","summary":"点击下一步，区分最终目的 IP 与每段链路的接收接口。","nodes":[["pc","电脑 A",80,80],["sw","交换机",240,80],["gw","路由器",400,80],["srv","服务器",560,80]],"links":[["pc","sw"],["sw","gw"],["gw","srv"]],"columns":["观察对象","当前值"],"steps":[{"title":"准备发送","text":"A 为 192.168.10.10/24，服务器为 192.0.2.20。目的不在本地 /24，A 选择网关 192.168.10.1。","rows":[["最终目的 IP","192.0.2.20"],["下一跳 IP","192.168.10.1"]]},{"title":"A → 交换机","text":"已解析网关 MAC 后，A 发出目的 MAC 为网关接口的帧。IP 包的目的仍是服务器。","active":[["pc","sw"]],"rows":[["目的 MAC","网关左侧接口"],["目的 IP","192.0.2.20"]]},{"title":"交换机 → 网关","text":"假设 MAC 表已有网关表项，交换机按目的 MAC 转发，不把自己的 MAC 填成帧的源地址。","active":[["sw","gw"]],"rows":[["目的 MAC","网关左侧接口（不变）"],["目的 IP","192.0.2.20（不变）"]]},{"title":"路由器 → 服务器","text":"路由器去掉入站链路封装，查路由、递减 IPv4 TTL 并更新头部校验和；在出口重新封装。","active":[["gw","srv"]],"rows":[["源 / 目的 MAC","路由器右侧接口 / 服务器"],["源 / 目的 IP","192.168.10.10 / 192.0.2.20"]]}],"boundary":"假设服务器网段直连路由器，链路、路由及 ARP 就绪，无 NAT、隧道、分片和策略阻断。IP 地址不变不代表整个 IP 头不变。箭头表示转发事件，不代表耗时或物理距离。","sources":[["RFC 1812 · IPv4 路由器要求","https://www.rfc-editor.org/rfc/rfc1812.html"]]},{"id":"vrp","unit":"ICT-001.01","title":"命令视图与保存，是两件事","summary":"逐步观察提示符与配置状态；命令仅作教学示例。","columns":["观察对象","当前状态"],"steps":[{"title":"用户视图","text":"<HUAWEI>：查看设备状态。从用户视图执行 system-view 进入系统视图。","rows":[["提示符","<HUAWEI>"],["运行配置 / 启动配置","旧配置 / 旧配置"]]},{"title":"系统视图","text":"[HUAWEI]：执行 interface GigabitEthernet 0/0/1，进入该接口视图。接口名以实际设备为准。","rows":[["提示符","[HUAWEI]"],["运行配置 / 启动配置","旧配置 / 旧配置"]]},{"title":"接口视图","text":"执行 description TO-LAN 后，接口描述进入运行配置。这个变更不等于已经写入启动配置。","rows":[["提示符","[HUAWEI-GigabitEthernet0/0/1]"],["运行配置 / 启动配置","新描述 / 旧配置"]]},{"title":"返回用户视图","text":"执行 return 回到用户视图。退出视图不撤销刚才的运行配置，也不自动保存。","rows":[["提示符","<HUAWEI>"],["运行配置 / 启动配置","新描述 / 旧配置"]]},{"title":"保存成功后","text":"执行 save 并按设备提示确认，保存成功后才更新启动配置。仍需回读配置并验证业务。","rows":[["提示符","<HUAWEI>"],["运行配置 / 启动配置","新描述 / 新描述"]]}],"boundary":"常见 VRP V200 即时生效配置模式示意；其他平台可能需要 commit。提示符、接口名、保存过程随版本变化。本演示不连接设备，不模拟重启，也不证明业务可达。","sources":[["华为 · system-view","https://info.support.huawei.com/hedex/api/pages/EDOC1100149308/AEJ0713J/17/resources/cli/system-view.html"],["华为 · 保存配置文件","https://info.support.huawei.com/hedex/api/pages/EDOC1000053358/YEF0907R/25/resources/en-us_task_0141547205.html"]]},{"id":"encapsulation","unit":"ICT-002.01","title":"封装：给同一份内容逐层加说明","summary":"点选字段可查看作用。块宽不表示字段字节数。","columns":["层次","交付对象"],"steps":[{"title":"应用数据","text":"以已经建立的 TCP 连接发送一段应用数据为例。","fields":[["应用数据","应用协议解释的内容。"]],"rows":[["应用层","对端应用"]]},{"title":"TCP 段","text":"TCP 加入源/目的端口、序号、确认号等头部信息。","fields":[["TCP 头","端口区分端点进程，序号与确认号支持有序可靠传输。"],["应用数据","TCP 提供字节流，不保留应用每次写入的边界。"]],"rows":[["传输层","端口标识的端点"]]},{"title":"IPv4 包","text":"IPv4 头给出源 IP、目的 IP、TTL 和上层协议等信息。","fields":[["IPv4 头","本例 Protocol=6，表示负载交给 TCP。"],["TCP 头","仍在 IP 负载内。"],["应用数据","仍在 TCP 负载内。"]],"rows":[["网际层","目的 IP 标识的网络端点"]]},{"title":"以太网帧","text":"帧头负责本链路交付，FCS 用于检测帧传输差错；接收端按相反顺序解析。","fields":[["目的 MAC · 6B","本链路的下一跳接口。"],["源 MAC · 6B","本链路发送接口。"],["类型 · 2B","本例为 0x0800，表示 IPv4。"],["IPv4 包","包含 IPv4 头、TCP 头和应用数据。"],["FCS · 4B","用于检测差错，不是加密或可靠重传机制。"]],"rows":[["网络接入层","本链路下一跳"]]}],"boundary":"Ethernet II + IPv4 + TCP 示例，无 VLAN 标签、IP/TCP 选项及分片。未画前导码、帧起始定界符及可能的填充；不是按比例的完整位布局。ARP 直接封装在以太网内，不套在 IPv4 中。","sources":[["RFC 894 · IP over Ethernet","https://www.rfc-editor.org/rfc/rfc894.html"],["RFC 9293 · TCP","https://www.rfc-editor.org/rfc/rfc9293.html"]]},{"id":"tcp","unit":"ICT-002.02","title":"三次握手：两端状态何时改变？","summary":"箭头以接收端收到该报文为本步完成点。","actors":["客户端","服务器"],"columns":["端点","TCP 状态"],"steps":[{"title":"初始状态","text":"服务器已被动打开并监听；客户端尚未发起连接。","rows":[["客户端","CLOSED"],["服务器","LISTEN"]]},{"title":"SYN 到达服务器","text":"客户端主动打开后进入 SYN-SENT。服务器收到 SYN，发送 SYN+ACK 后进入 SYN-RECEIVED。","message":[0,1,"SYN · Seq=100"],"rows":[["客户端","SYN-SENT"],["服务器","SYN-RECEIVED"]]},{"title":"SYN+ACK 到达客户端","text":"客户端收到合法 SYN+ACK 后进入 ESTABLISHED，并发出最后的 ACK。服务器此时仍等待 ACK。","message":[1,0,"SYN+ACK · Seq=500 · Ack=101"],"rows":[["客户端","ESTABLISHED"],["服务器","SYN-RECEIVED"]]},{"title":"ACK 到达服务器","text":"服务器收到合法 ACK 后进入 ESTABLISHED。SYN 各占用一个序号，因此确认号分别为 101 和 501。","message":[0,1,"ACK · Seq=101 · Ack=501"],"rows":[["客户端","ESTABLISHED"],["服务器","ESTABLISHED"]]}],"boundary":"普通主动/被动打开，无丢包、重传、同时打开或 SYN 携带数据，初始序号为教学选值。ACK 本身不消耗序号；握手完成不等于业务请求已成功，也不代表连接已加密。","sources":[["RFC 9293 §3.5 · 连接建立","https://www.rfc-editor.org/rfc/rfc9293.html#section-3.5"]]},{"id":"arp-local","unit":"ICT-002.04","title":"ARP：问的是本地终端，还是网关？","summary":"切换场景会回到起点，并清空这次演示的缓存。","variant":"arp","label":"同网段目的","actors":["A · 192.168.10.10","B · 192.168.10.20"],"columns":["A 的 ARP 缓存 IP","MAC（示例末字节）"],"steps":[{"title":"选择下一跳","text":"A 的前缀为 /24。B 位于同网段，下一跳为 B 自己，缓存为空。","rows":[]},{"title":"广播询问","text":"ARP 请求询问谁拥有 192.168.10.20；以太网目的 MAC 为 FF:FF:FF:FF:FF:FF。同 VLAN 其他成员也会收到。","message":[0,1,"请求 · Who has 192.168.10.20?"],"rows":[]},{"title":"B 单播回应","text":"B 回答自己的 MAC。A 收到响应后建立映射；交换机的 MAC 表是另一张表。","message":[1,0,"响应 · 192.168.10.20 is at …0B"],"rows":[["192.168.10.20","02:00:00:00:00:0B"]]},{"title":"交付数据帧","text":"A 将目的 IP 为 B 的 IP 包，装入目的 MAC 为 B 的以太网帧发送。","message":[0,1,"IPv4 数据 · 目的 MAC=…0B"],"rows":[["192.168.10.20","02:00:00:00:00:0B"]]}],"boundary":"IPv4 以太网、同一 VLAN、无冲突或攻击；缓存开始为空，只显示 A 的缓存。图仅画通信双方，请求实际广播给本 VLAN 其他成员；不模拟超时、代理 ARP 或非请求方缓存更新。","sources":[["RFC 826 · ARP","https://www.rfc-editor.org/rfc/rfc826.html"]]},{"id":"arp-gateway","unit":"ICT-002.04","title":"ARP：问的是本地终端，还是网关？","summary":"切换场景会回到起点，并清空这次演示的缓存。","variant":"arp","label":"跨网段目的","actors":["A · 192.168.10.10","网关 · 192.168.10.1"],"columns":["A 的 ARP 缓存 IP","MAC"],"steps":[{"title":"选择网关","text":"A 为 /24，目的为 192.0.2.20。按本例默认路由，下一跳选择 192.168.10.1。","rows":[]},{"title":"广播询问网关","text":"A 询问 192.168.10.1 的 MAC，目的 MAC 为全 F。不对远端 192.0.2.20 广播 ARP。","message":[0,1,"请求 · Who has 192.168.10.1?"],"rows":[]},{"title":"网关回应","text":"网关本地接口返回自己的 MAC。ARP 广播请求不会被路由器原样转发到服务器网段。","message":[1,0,"响应 · 192.168.10.1 is at …01"],"rows":[["192.168.10.1","02:00:00:00:00:01"]]},{"title":"先交给网关","text":"帧的目的 MAC 是网关；包的目的 IP 仍为 192.0.2.20。后续交付由网关查路由决定。","message":[0,1,"IPv4 数据 · 目的 IP=192.0.2.20"],"rows":[["192.168.10.1","02:00:00:00:00:01"]]}],"boundary":"假设默认网关在 A 的直连 /24 内，接口可用。只画 A 到网关这一段，不模拟远端网络。广播请求也会到达本 VLAN 其他成员。","sources":[["RFC 826 · ARP","https://www.rfc-editor.org/rfc/rfc826.html"],["RFC 1812 · 下一跳选择","https://www.rfc-editor.org/rfc/rfc1812.html"]]}],"glossary":[{"id":"vrp","terms":["VRP系统","VRP"],"plain":"华为网络设备的操作与管理平台。","detail":"命令能否使用取决于设备型号、软件版本、权限和所在视图；运行配置与启动配置要分开理解。"},{"id":"mac","terms":["MAC地址","MAC 地址","MAC"],"plain":"本地链路上识别网络接口的地址。","detail":"以太网通常使用 48 位 MAC。交换机按 VLAN 和目的 MAC 查表，按收到帧的源 MAC 学习入口。MAC 不是跨互联网寻找路径的地址。"},{"id":"ip","terms":["IPv4地址","IP地址","IP 地址","IPv4","IP"],"plain":"帮助网络把包送向目的地的逻辑地址。","detail":"IPv4 地址有 32 位，需结合掩码判断网络前缀；跨网段交给下一跳，IP 不保证到达、顺序或无重复。"},{"id":"gateway","terms":["默认网关","网关"],"plain":"离开本地网段时，先把包交给的路由接口。","detail":"主机按路由选下一跳。在 IPv4 以太网中，通常先用 ARP 解析下一跳 IP 的 MAC，而不是解析远端服务器的 MAC。"},{"id":"arp","terms":["ARP"],"plain":"在本链路上询问某个 IPv4 地址对应哪个 MAC 的协议。","detail":"请求通常用以太网广播，响应通常单播。ARP 缓存存 IP→MAC，交换机 MAC 表存 VLAN+MAC→端口，两者不是同一张表。"},{"id":"tcpip","terms":["TCP/IP协议架构","TCP/IP架构","TCP/IP"],"plain":"围绕互联网通信分工协作的一组协议。","detail":"通常按应用层、传输层、网际层和网络接入层理解。TCP 是其中一种传输层协议，IP 属于网际层；并非所有应用都使用 TCP。"},{"id":"tcp","terms":["TCP"],"plain":"TCP 向两端应用提供有序、可靠的字节流传输。","detail":"TCP/IP 是协议族的名称，不是单独一种协议。TCP 用端口、序号、确认、重传、窗口等机制维护连接；不自带加密，也不保留应用写入边界。"},{"id":"udp","terms":["UDP"],"plain":"把应用的一份消息作为数据报传送的传输层协议。","detail":"UDP 保留消息边界，自身不建立 TCP 式连接，不保证到达、顺序或重传。应用可以在其上实现额外保障。"},{"id":"vlan","terms":["VLAN"],"plain":"在交换网络中划分二层广播域的逻辑分组。","detail":"泛洪只面向所属 VLAN 中符合转发条件的其他端口；跨 VLAN 通信通常需要三层转发。"},{"id":"frame","terms":["以太网帧","数据帧","帧"],"plain":"在一段链路上传送数据的封装单元。","detail":"Ethernet II 帧包含目的与源 MAC、类型、数据及 FCS；经路由器三层转发时，出口使用新的链路封装。"},{"id":"encapsulation","terms":["封装"],"plain":"给上层内容加上本层处理所需的头部等信息。","detail":"例如 TCP 段放进 IP 包，再放进以太网帧。不是沿途每台设备都重新生成全部上层内容。"},{"id":"port","terms":["端口号"],"plain":"传输层用于区分通信端点的数字。","detail":"TCP/UDP 端口号与协议、IP 地址等共同标识端点，不是设备上的物理插口。"},{"id":"prefix","terms":["前缀长度","子网掩码","掩码"],"plain":"指明 IP 地址中哪一部分属于网络。","detail":"/26 表示 IPv4 前 26 位是网络位，剩余 6 位为主机位；判断同网段需比较按掩码计算出的网络地址。"},{"id":"flood","terms":["泛洪"],"plain":"把帧复制给同一 VLAN 内其他可转发端口。","detail":"广播和未知单播都可能泛洪；未知单播的目的 MAC 仍是单播地址。入口端口不再作为出口。"},{"id":"nat","terms":["NAPT","NAT"],"plain":"在转发途中改变报文中的 IP 地址表示。","detail":"NAPT 还转换传输层端口。转换、路由选择和安全放行是不同职责，返回流量需匹配相应映射。"},{"id":"dhcp","terms":["DHCP"],"plain":"让终端租用 IP 地址并获取网络参数的协议。","detail":"常见首次分配过程为 Discover、Offer、Request、ACK；跨广播域通常要中继，租约需要续期。"},{"id":"telnet","terms":["Telnet"],"plain":"通过 TCP 使用远端设备命令行的协议。","detail":"传统 Telnet 不加密账号和会话内容；本课程只用于隔离实验，并与 SSH 比较。"},{"id":"ftp","terms":["FTP"],"plain":"用控制连接和独立数据连接传输文件的协议。","detail":"控制连接通常到服务器 TCP 21；主动与被动模式的数据连接方向不同，登录成功不证明数据通道可通。"},{"id":"ttl","terms":["TTL"],"plain":"限制 IPv4 包继续被路由转发的生存字段。","detail":"通常每经过一次路由转发至少减 1；耗尽时丢弃。路由器也相应更新 IPv4 头部校验和。"},{"id":"dns","terms":["DNS"],"plain":"把域名查询成 IP 等记录的服务。","detail":"域名解析成功与业务连接成功是两件事；直接 IP 可达但域名失败时，应检查解析路径与记录。"},{"id":"icmp","terms":["ICMP"],"plain":"IP 网络传递差错与诊断消息的协议。","detail":"ping 常用 ICMP 回显测试可达性；成功不证明 TCP 端口、TLS 或应用正常，失败也可能来自过滤。"},{"id":"tls","terms":["TLS"],"plain":"为通信提供加密、完整性和身份验证的协议。","detail":"通常位于应用与传输之间；TCP 握手成功不等于 TLS 握手或证书验证成功。"},{"id":"ssh","terms":["SSH"],"plain":"带加密保护的远程登录等服务协议。","detail":"和传统 Telnet 相比可保护会话内容，但仍需正确验证服务器身份并控制账号权限。"},{"id":"broadcast","terms":["广播域","广播"],"plain":"广播是把链路消息发给本广播域内所有接收者。","detail":"广播域是二层广播能到达的范围，通常由 VLAN 划分；路由器一般不原样转发二层广播帧。"},{"id":"unicast","terms":["未知单播","单播"],"plain":"单播的目的地址标识一个接收接口。","detail":"未知单播指交换机尚无该 VLAN 中目的 MAC 的表项；它可能被泛洪，但目的 MAC 不会变成广播地址。"},{"id":"next-hop","terms":["下一跳"],"plain":"本次转发要先交给的相邻网络端点。","detail":"最终目的在远端时，下一跳通常是路由器接口；在本地直连网络时，下一跳可以是目的主机本身。"},{"id":"routing","terms":["路由器"],"plain":"连接不同 IP 网络，并按路由表转发 IP 包的设备。","detail":"路由器连接不同的 IP 网络；普通路由转发会递减 TTL 并重新封装出口链路层，交换机通常按二层地址转发。"},{"id":"fcs","terms":["FCS"],"plain":"以太网帧末尾用于检测差错的校验字段。","detail":"采用 CRC 检测传输差错；不能纠错，不负责重传，也不能防止恶意篡改。"},{"id":"syn","terms":["SYN"],"plain":"TCP 建立连接时用于同步初始序号的标志。","detail":"SYN 会消耗一个序号；ACK 是确认标志，确认号指接收端下一步期望的序号，纯 ACK 不消耗序号。"},{"id":"view","terms":["用户视图","系统视图","接口视图"],"plain":"命令行当前所在的操作范围。","detail":"用户视图通常显示尖括号，配置视图通常显示方括号；system-view 进入系统视图，interface 进入接口，quit 退一级，return 回用户视图。"},{"id":"config","terms":["运行配置","启动配置"],"plain":"运行配置是当前生效的设置；启动配置供设备下次启动读取。","detail":"修改、退出视图与保存是不同操作。运行配置变更后，只有按目标设备要求成功保存并核对启动文件，才可预期重启后保留。"},{"id":"route","terms":["路由"],"plain":"决定 IP 包从哪个出口交给哪个下一跳的路径信息。","detail":"主机和路由器按路由选择下一跳；转发表常按目的 IP 做最长前缀匹配，不能把路由选择与 NAT 或安全放行混为一谈。"}]};
